def gradients(image):
    g = gray(image)
    dx = cv.Sobel(g, cv.CV_32F, 1, 0, ksize=3)
    dy = cv.Sobel(g, cv.CV_32F, 0, 1, ksize=3)
    return dx, dy, np.hypot(dx, dy), np.degrees(np.arctan2(dy, dx))
